    const options=inside.length?inside:ordered.filter(s=>!selected.some(t=>t.index===s.index));
    const choice=options.slice().sort((a,b)=>b.tall-a.tall||a.index-b.index).find(s=>!selected.some(t=>t.index===s.index));
