    const ml=cubic(left,[s.x-s.bw*.6,s.height-s.tall*.35],[s.tipX-s.lean*.3,s.tipY+s.tall*.22],tip,.5);
    const mr=cubic(right,[s.x+s.bw,s.height-s.tall*.32],[s.tipX-s.lean*.13,s.tipY+s.tall*.30],tip,.5);
    const center=[s.x,s.height],mc=[(ml[0]+mr[0])*.5,(ml[1]+mr[1])*.5],rootX=(s.x/s.width-.5)*.55;
    const yaw=yaws[leaf],co=Math.cos(yaw),si=Math.sin(yaw),foldWidth=s.bw*.55/s.width,base=positions.length/3;
