    const tipLeft=cubic(left,[s.x-s.bw*.6,s.height-s.tall*.35],[s.tipX-s.lean*.3,s.tipY+s.tall*.22],tip,.66),tipRight=cubic(right,[s.x+s.bw,s.height-s.tall*.32],[s.tipX-s.lean*.13,s.tipY+s.tall*.30],tip,.66),tipUv=[(tipLeft[0]+tipRight[0])*.5,(tipLeft[1]+tipRight[1])*.5];
